 function closeEditor(){setEditor(null);setRelatedDraft(null);setError('')}
 function beginRelated(action:PreviewRelatedAction,checkId?:string){if(!canEdit||busy||privateBusy||!taskView)return;const source=data.tasks.find(t=>t.id===taskView.id);if(!source)return;setError('');if(action==='run-again'){const existing=data.tasks.find(t=>t.previousRunId===source.id);if(existing){readTask(existing);return}editTask(nextRun(source,uid()));setTaskView(source);return}if(action==='event-check'){editTask({...newTask(source.projectId),title:('Check after: '+source.title).slice(0,250),trigger:'Event-based',eventName:'After restart / recovery',notes:source.resolution||source.notes,relatedIds:[source.id]});setRelatedDraft({sourceId:source.id});setTaskView(source);return}if(action==='link'){setLinkSource(source);return}if(action==='sop'){editSop({...newSop(source.projectId),resourceType:'SOP',title:(source.title+' — SOP').slice(0,250),updateNote:'Created from '+source.tracker.toLowerCase()+' #'+source.number});setSopItemIds([source.id]);setTaskView(source);return}try{const draft=relatedTask(source,action,uid(),checkId);editTask({...draft,title:action==='follow-up'||checkId?draft.title:''});setRelatedDraft({sourceId:source.id,checkId});setTaskView(source)}catch(e){setError(e instanceof Error?e.message:'Unable to create related work.')}}
 async function linkWork(targetId:string){if(!canEdit||busy||privateBusy||!linkSource)return;try{const next=linkExistingWork(data,linkSource.id,targetId);if(next===data){setLinkSource(null);return}if(await commit(next)){setLinkSource(null);setNotice('Related item linked.')}}catch(e){setError(e instanceof Error?e.message:'Unable to link this item.')}}
 async function saveEditor(e:React.FormEvent){e.preventDefault();if(!editor)return;try{let next:Planner;if(kind==='project'){const p=editor as Project;const projects=data.projects.some(x=>x.id===p.id)?data.projects.map(x=>x.id===p.id?p:x):[...data.projects,p];next={...data,projects}}else if(kind==='sop'){const sop=editor as Sop;next=saveSop(data,sop,sopItemIds)}else{const t=editor as Task;next=relatedDraft?withRelatedTask(data,t,relatedDraft):{...data,tasks:data.tasks.some(x=>x.id===t.id)?data.tasks.map(x=>x.id===t.id?t:x):[...data.tasks,t]}}if(await commit(next)){setEditor(null);setRelatedDraft(null)}}catch(e){setError(e instanceof Error?e.message:'Save failed. Your draft is still open.')}}
 async function makeSop(t:Task){const tasks=data.tasks.map(x=>x.id===t.id?t:x);if(!await commit({...data,tasks}))return;editSop({...newSop(t.projectId),resourceType:'SOP',title:(t.title+' — SOP').slice(0,250),updateNote:'Created from issue #'+t.number});setSopItemIds([t.id]);}
 async function saveTaskDraft(t:Task){const tasks=data.tasks.some(x=>x.id===t.id)?data.tasks.map(x=>x.id===t.id?t:x):[...data.tasks,t];return commit({...data,tasks});}
 async function promoteConfirmation(t:Task,c:Confirmation,tracker:'Task'|'Issue'){if(relatedDraft){setError('Save this related item before creating more linked work.');return}if(!t.title.trim()||!c.label.trim()){setError('Enter a subject and confirmation question first.');return}if(c.linkedTaskId){setError('This confirmation already has linked work.');return}const child={...newTask(t.projectId,tracker),...promotionDetails(t,c,tracker)} as Task;const parent={...t,checklist:t.checklist.map(x=>x.id===c.id?{...x,linkedTaskId:child.id,status:tracker==='Issue'?'Blocked' as const:x.follow?'Waiting' as const:'Pending' as const,checkedAt:''}:x)};const tasks=[...data.tasks.filter(x=>x.id!==t.id),parent,child];const saved=await commit({...data,tasks});if(saved){const current=saved.tasks.find(x=>x.id===child.id);if(current)editTask(current)}}

 async function openLinked(id:string){if(relatedDraft){setError('Save this related item before opening other work.');return}if(editor&&kind==='task'){const saved=await saveTaskDraft(editor as Task);if(saved){const linked=saved.tasks.find(t=>t.id===id);if(linked)editTask(linked)}}}
 async function createExecution(t:Task){if(relatedDraft){setError('Save this related item before creating more work.');return}const saved=await saveTaskDraft(t);if(!saved)return;const current=saved.tasks.find(x=>x.id===t.id)!;editTask({...newTask(t.projectId),title:('Follow up: '+t.title).slice(0,250),relatedIds:[t.id],sopIds:referenceIds(t),notes:('Readiness confirmed in work item #'+current.number+'.\n\n'+t.checklist.map(c=>`${c.label}: ${c.status} — ${plainText(c.result||c.note)}`).join('\n')).slice(0,5000)});}
 async function remove(){if(!editor)return;const id=editor.id;if(!confirm(kind==='project'?'Delete this project? Its work items and SOPs become unassigned.':kind==='sop'?'Delete this procedure and its version history?':'Delete this item and its history? Relationships will be removed.'))return;let next:Planner;if(kind==='project')next={...data,projects:data.projects.filter(p=>p.id!==id),tasks:data.tasks.map(t=>t.projectId===id?{...t,projectId:''}:t),sops:data.sops.map(s=>s.projectId===id?{...s,projectId:''}:s)};else if(kind==='sop')next=removeSop(data,id);else next={...data,tasks:data.tasks.filter(t=>t.id!==id).map(t=>({...t,parentId:t.parentId===id?'':t.parentId,relatedIds:t.relatedIds.filter(x=>x!==id),checklist:t.checklist.map(c=>c.linkedTaskId===id?{...c,linkedTaskId:''}:c)})),sops:data.sops.map(s=>s.sourceId===id?{...s,sourceId:''}:s)};if(await commit(next)){setEditor(null);setRelatedDraft(null);if(taskView?.id===id)setTaskView(null);if(sopView?.id===id)setSopView(null)}}

